import{_ as e,o as s,c as t,a0 as i}from"./chunks/framework.BxCN1dRw.js";const k=JSON.parse('{"title":"跟做：把知识库部署到单机生产并验证启停与降级","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/single-machine-production"},"headers":[],"relativePath":"tutorials/single-machine-production.md","filePath":"tutorials/single-machine-production.md"}'),d={name:"tutorials/single-machine-production.md"};function o(n,a,r,p,l,h){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="跟做-把知识库部署到单机生产并验证启停与降级" tabindex="-1">跟做：把知识库部署到单机生产并验证启停与降级 <a class="header-anchor" href="#跟做-把知识库部署到单机生产并验证启停与降级" aria-label="Permalink to &quot;跟做：把知识库部署到单机生产并验证启停与降级&quot;">​</a></h1><p>本章回答“模板如何上单机生产”。一台 Docker 主机、一个 Caddy TLS 入口，静态 Web 由 Caddy 直接服务，API、Worker、PostgreSQL、Redis 与 RustFS 全部留在内部网络、不发布任何端口；数据库迁移与存储初始化永远显式执行。生产组合不是开发 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/compose.yaml" target="_blank" rel="noreferrer">compose</a> 的复制品：它有自己的<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/compose.production.yaml" target="_blank" rel="noreferrer">组合文件</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/deploy/production/Dockerfile" target="_blank" rel="noreferrer">镜像构建</a>与<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/deploy/production/Caddyfile" target="_blank" rel="noreferrer">入口配置</a>，并且用测试锁住这些差异。</p><h2 id="_1-准备部署环境与密钥" tabindex="-1">1. 准备部署环境与密钥 <a class="header-anchor" href="#_1-准备部署环境与密钥" aria-label="Permalink to &quot;1. 准备部署环境与密钥&quot;">​</a></h2><p>复制模板并填写部署环境文件：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/production/env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR .env.production</span></span></code></pre></div><p>需要修改的最小集合：<code>DOMAIN</code>（TLS 域名，Caddy 据此自动签发证书——公网域名走 ACME，localhost 走本地 CA）、<code>POSTGRES_PASSWORD</code>、<code>S3_ACCESS_KEY</code>/<code>S3_SECRET_KEY</code>。<code>MAIL_SMTP_HOST</code> 留空表示邮件关闭（注册与写作不受影响，只有重置邮件不发）；启用 SMTP 时必须同时设置 <code>MAIL_ENCRYPTION_KEY</code>（32 字节 hex，api 与 worker 一致），之后即使 SMTP 失联，注册与写作也不受影响，投递任务留在队列按租约重试。<code>TELEMETRY_ENDPOINT</code> 留空表示不上报 OTLP；采集器不可达也不阻塞业务。</p><p>这个文件装着生产密钥，已被 <code>.gitignore</code> 与 <code>.dockerignore</code> 排除，永远不进入镜像或仓库。组合文件里的服务 <code>env_file</code> 走的是 <code>ENV_FILE</code> 环境变量，而 <code>--env-file</code> 只喂给插值——<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/justfile" target="_blank" rel="noreferrer">justfile</a> 的 <code>production-*</code> 配方已代为传递 <code>ENV_FILE</code>，手动调用 docker compose 时必须带上它。所有键的语义与校验规则见<a href="./../reference/config">生成配置参考</a>或 <code>deploy/production/env.production.example</code> 内注释。</p><h2 id="_2-构建、启动与显式迁移" tabindex="-1">2. 构建、启动与显式迁移 <a class="header-anchor" href="#_2-构建、启动与显式迁移" aria-label="Permalink to &quot;2. 构建、启动与显式迁移&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # 构建 Web 产物与应用镜像（不需要环境文件）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 依赖 → 显式迁移 → 应用</span></span></code></pre></div><p><code>production-up</code> 的顺序是有意的：先 <code>--wait</code> 等 PostgreSQL/Redis/RustFS 健康，再以一次性容器跑 <code>migrate</code> 与 <code>storage-init</code>（compose 的 <code>ops</code> profile，普通 <code>up</code> 看不见它们），最后才启动 api、worker、caddy 并等待健康。API 与 Worker 从不偷偷迁移：行为测试让二进制对着空数据库启动，断言 <code>/health/ready</code> 持续 503（<code>database.unavailable</code>/<code>worker.unavailable</code>）、五秒内 <code>public</code> schema 仍然零表、进程保持存活（<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/apps/api/tests/migration.rs" target="_blank" rel="noreferrer">API 侧</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/apps/worker/tests/no_implicit_migration.rs" target="_blank" rel="noreferrer">Worker 侧</a>）。</p><p>镜像构建是多阶段：Rust 构建阶段带 registry/target 缓存挂载，运行时是 slim Debian + 非 root 用户 + 只读根文件系统（<code>read_only: true</code>、tmpfs <code>/tmp</code>），基础镜像按 digest 固定。<code>migrations/</code> 会被 <code>sqlx::migrate!</code> 在编译期嵌入，因此必须留在构建上下文里。</p><h2 id="_3-验证入口与主旅程" tabindex="-1">3. 验证入口与主旅程 <a class="header-anchor" href="#_3-验证入口与主旅程" aria-label="Permalink to &quot;3. 验证入口与主旅程&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-smoke</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/production-smoke.mjs" target="_blank" rel="noreferrer">冒烟脚本</a>随机生成一套密钥、启动完整生产组合，然后经真实 Caddy TLS 链完成：入口检查（<code>/health/live</code> 200、首页带 HSTS 与 CSP、明文 HTTP 重定向）、主旅程（注册成 owner、写文档、传附件并回读）、重启持久性、Redis/RustFS/PostgreSQL 三种故障的降级行为、Worker 停机后排队的导出恢复，以及 API 与 Worker 的优雅停止。整个旅程刻意在“邮件已配置但 SMTP 失联、遥测采集器不可达”的环境里跑——注册与写作全程可用，正是降级矩阵承诺的行为。每个阶段失败都会以 <code>[阶段名]</code> 前缀抛出，脚本结束时自动 <code>down -v</code> 清理。</p><p>手工抽查入口也可以：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 期待 308 → https</span></span></code></pre></div><p>预签名对象 URL 之所以能经入口工作，是因为应用以 <code>S3_PUBLIC_ENDPOINT</code>（即 <code>APP_ORIGIN</code>）签名，而 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/deploy/production/Caddyfile" target="_blank" rel="noreferrer">Caddyfile</a> 把 <code>/&lt;bucket&gt;/*</code> 原样转发给 rustfs:9000，路径与 Host 都不改动，v4 签名保持有效。</p><h2 id="_4-停止、重启与降级规则" tabindex="-1">4. 停止、重启与降级规则 <a class="header-anchor" href="#_4-停止、重启与降级规则" aria-label="Permalink to &quot;4. 停止、重启与降级规则&quot;">​</a></h2><p><code>docker compose restart api worker</code>（或 stop/start）验证的是同一件事：会话 Cookie 与数据都活过容器替换，因为状态只落在 PostgreSQL 与对象卷里。停止超时由组合文件的 <code>stop_grace_period</code> 与进程内预算匹配：</p><table tabindex="0"><thead><tr><th>容器</th><th>进程内停止预算</th><th>stop_grace_period</th></tr></thead><tbody><tr><td>api</td><td>3s HTTP drain + 1s 连接池 + 有界遥测刷新（合计 ≤15s）</td><td>30s</td></tr><tr><td>worker</td><td>api 预算 + <code>JOB_SHUTDOWN_SECS</code>（默认 10s）在手任务收尾（合计 ≤25s）</td><td>45s</td></tr><tr><td>其余</td><td>无自定义逻辑，默认停止即可</td><td>10–30s</td></tr></tbody></table><p>冒烟脚本会掐表验证这一点：api 的停止耗时必须明显低于 30s 宽限期（证明是自行退出而不是被强杀），日志里出现 <code>draining HTTP requests</code>；Worker 停止同理，日志里出现 <code>stopping worker claims and draining current work</code>。</p><p>非核心依赖故障按规格矩阵降级，每种行为都被冒烟覆盖：</p><table tabindex="0"><thead><tr><th>故障</th><th>行为</th></tr></thead><tbody><tr><td>PostgreSQL 停止</td><td><code>/health/ready</code> 变 503，业务读返回受控 503（带 <code>request_id</code>），恢复后无需重启即恢复 200</td></tr><tr><td>Redis 停止</td><td>缓存回退数据库，注册与写作继续；就绪探针只看数据库，容器不会被误判为不健康</td></tr><tr><td>RustFS 停止</td><td>Markdown 仍在 PostgreSQL 可读；新上传的 PUT 失败、完成返回受控 503；恢复后重试成功</td></tr><tr><td>邮件已配置但失联</td><td>注册与写作不受影响；重置/验证邮件任务留在队列按租约重试</td></tr><tr><td>遥测采集器不可达</td><td>业务不受影响；批量导出有界，进程停止时按截止时间刷新</td></tr></tbody></table><p>Worker 停机时不丢工作：导出请求照常 202 受理，Worker 回来后从数据库任务表认领并完成（租约由 <code>JOB_LEASE_SECS</code> 保护）。</p><h2 id="_5-升级与维护窗口" tabindex="-1">5. 升级与维护窗口 <a class="header-anchor" href="#_5-升级与维护窗口" aria-label="Permalink to &quot;5. 升级与维护窗口&quot;">​</a></h2><p>升级 = 换镜像 + 显式迁移，顺序固定：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 或只 stop api worker 做滚动窗口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 显式执行新迁移</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span></span></code></pre></div><p>失败处理是同一条命令的自然结果：<code>migrate</code> 一次性容器以非零退出时，<code>production-up</code> 在启动应用之前中止，数据库停留在上一个成功迁移，旧容器停止、新容器尚未接管——排除问题（最常见是环境文件缺键或数据库不可达）后重跑 <code>production-migrate</code> 即可，已成功的迁移不会重复执行。</p><p><code>docker compose up -d</code> 只重建镜像或配置变化的服务；数据卷（PostgreSQL 数据、对象存储、Caddy 证书）在升级之间持久。任何时刻不要手工进入容器改数据——恢复路径见<a href="./backup-restore">备份与独立环境恢复演练</a>。</p><h2 id="_6-运行本章检查" tabindex="-1">6. 运行本章检查 <a class="header-anchor" href="#_6-运行本章检查" aria-label="Permalink to &quot;6. 运行本章检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/production-compose.test.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 组合文件与安全属性</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-smoke</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # 真实组合全旅程</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/tests/tooling/production-compose.test.mjs" target="_blank" rel="noreferrer">组合测试</a>在每次 <code>just check</code> 里校验生产组合的结构属性：只有 Caddy 发布端口、长驻服务都有健康检查与资源上限、迁移服务藏在 <code>ops</code> profile 且不被依赖、API/Worker 命令里没有 migrate、只读根文件系统、env 模板不含真实密钥、<code>.dockerignore</code> 排除 <code>.secrets</code> 与 <code>.env*</code>。重点是：迁移显式、入口唯一、故障按矩阵降级、宽限期匹配停止预算。</p><hr><p>源码版本：<code>0b53e60ef0f0</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/docs/tutorials/21-single-machine-production.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,34)])])}const u=e(d,[["render",o]]);export{k as __pageData,u as default};
